{
  "id": "p_002",
  "summary": "Especificación JSON de una API REST minimalista para gestionar tareas, con recurso task, endpoints CRUD, métodos HTTP, códigos de estado, convenciones y ejemplos.",
  "approach": "Se define un único recurso task expuesto en /tasks. El servidor genera id como UUID v4 y los timestamps createdAt y updatedAt en formato ISO 8601. GET /tasks lista todas las tareas, POST /tasks crea una tarea, GET /tasks/{id} obtiene una tarea, PATCH /tasks/{id} actualiza parcialmente una tarea y DELETE /tasks/{id} la elimina. Todas las solicitudes y respuestas usan application/json. Se elige PATCH en lugar de PUT para actualizaciones parciales y se evita autenticación, paginación, filtros u operaciones masivas.",
  "tradeoffs": [
    "PATCH permite actualizaciones parciales sin obligar al cliente a enviar el objeto task completo.",
    "La ausencia de autenticación simplifica la API, pero la hace inadecuada para entornos reales multiusuario.",
    "Listar todas las tareas sin paginación reduce la complejidad, pero puede escalar mal con volúmenes grandes.",
    "El formato de error único facilita el consumo de la API, pero no cubre escenarios avanzados de validación o trazabilidad."
  ],
  "evidence": [
    "RFC 9110 define la semántica de métodos HTTP como GET, POST, PUT, PATCH y DELETE.",
    "RFC 4122 define el formato de identificadores UUID.",
    "RFC 8259 define application/json como formato de intercambio de datos."
  ],
  "artifacts": [],
  "api": {
    "name": "tasks-api",
    "version": "1.0.0",
    "description": "API REST minimalista para gestionar tareas sin autenticación ni características avanzadas.",
    "baseUrl": "/",
    "contentType": "application/json",
    "resource": {
      "name": "task",
      "description": "Recurso principal que representa una tarea.",
      "fields": [
        {
          "name": "id",
          "type": "string",
          "format": "uuid",
          "required": true,
          "generatedByServer": true,
          "description": "Identificador único de la tarea.",
          "example": "3fa85f64-5717-4562-b3fc-2c963f66afa6"
        },
        {
          "name": "title",
          "type": "string",
          "required": true,
          "description": "Título de la tarea.",
          "constraints": {
            "minLength": 1,
            "maxLength": 200
          },
          "example": "Comprar pan"
        },
        {
          "name": "completed",
          "type": "boolean",
          "required": true,
          "default": false,
          "description": "Indica si la tarea está completada.",
          "example": false
        },
        {
          "name": "createdAt",
          "type": "string",
          "format": "date-time",
          "required": true,
          "generatedByServer": true,
          "description": "Fecha y hora de creación de la tarea.",
          "example": "2026-01-15T09:30:00Z"
        },
        {
          "name": "updatedAt",
          "type": "string",
          "format": "date-time",
          "required": true,
          "generatedByServer": true,
          "description": "Fecha y hora de la última actualización de la tarea.",
          "example": "2026-01-15T09:30:00Z"
        }
      ]
    },
    "endpoints": [
      {
        "method": "GET",
        "path": "/tasks",
        "purpose": "Listar todas las tareas sin paginación ni filtros.",
        "requestBody": null,
        "successResponse": {
          "status": 200,
          "bodyDescription": "Arreglo de objetos task.",
          "exampleReference": "examples.taskList"
        },
        "errorResponses": [
          {
            "status": 405,
            "reason": "Método no permitido."
          }
        ]
      },
      {
        "method": "POST",
        "path": "/tasks",
        "purpose": "Crear una tarea.",
        "requestBody": {
          "required": true,
          "contentType": "application/json",
          "fields": [
            {
              "name": "title",
              "type": "string",
              "required": true
            },
            {
              "name": "completed",
              "type": "boolean",
              "required": false,
              "default": false
            }
          ],
          "example": {
            "title": "Comprar pan",
            "completed": false
          }
        },
        "successResponse": {
          "status": 201,
          "headers": {
            "Location": "/tasks/{id}"
          },
          "bodyDescription": "Objeto task creado, con id, createdAt y updatedAt generados por el servidor.",
          "exampleReference": "examples.task"
        },
        "errorResponses": [
          {
            "status": 400,
            "reason": "Cuerpo JSON inválido o malformado."
          },
          {
            "status": 415,
            "reason": "Content-Type distinto de application/json."
          },
          {
            "status": 422,
            "reason": "Validación semántica fallida, por ejemplo title vacío o ausente."
          }
        ]
      },
      {
        "method": "GET",
        "path": "/tasks/{id}",
        "purpose": "Obtener una tarea por identificador.",
        "pathParameters": [
          {
            "name": "id",
            "type": "string",
            "format": "uuid",
            "required": true
          }
        ],
        "requestBody": null,
        "successResponse": {
          "status": 200,
          "bodyDescription": "Objeto task correspondiente al identificador solicitado.",
          "exampleReference": "examples.task"
        },
        "errorResponses": [
          {
            "status": 400,
            "reason": "El parámetro id no es un UUID válido."
          },
          {
            "status": 404,
            "reason": "La tarea no existe."
          }
        ]
      },
      {
        "method": "PATCH",
        "path": "/tasks/{id}",
        "purpose": "Actualizar parcialmente una tarea. Solo se permiten los campos title y completed.",
        "pathParameters": [
          {
            "name": "id",
            "type": "string",
            "format": "uuid",
            "required": true
          }
        ],
        "requestBody": {
          "required": true,
          "contentType": "application/json",
          "fields": [
            {
              "name": "title",
              "type": "string",
              "required": false
            },
            {
              "name": "completed",
              "type": "boolean",
              "required": false
            }
          ],
          "constraints": "El cuerpo debe incluir al menos uno de los campos permitidos.",
          "example": {
            "completed": true
          }
        },
        "successResponse": {
          "status": 200,
          "bodyDescription": "Objeto task actualizado. El servidor actualiza updatedAt.",
          "exampleReference": "examples.taskUpdated"
        },
        "errorResponses": [
          {
            "status": 400,
            "reason": "Cuerpo JSON inválido, vacío o con campos no permitidos."
          },
          {
            "status": 404,
            "reason": "La tarea no existe."
          },
          {
            "status": 415,
            "reason": "Content-Type distinto de application/json."
          },
          {
            "status": 422,
            "reason": "Validación semántica fallida, por ejemplo title vacío."
          }
        ]
      },
      {
        "method": "DELETE",
        "path": "/tasks/{id}",
        "purpose": "Eliminar una tarea.",
        "pathParameters": [
          {
            "name": "id",
            "type": "string",
            "format": "uuid",
            "required": true
          }
        ],
        "requestBody": null,
        "successResponse": {
          "status": 204,
          "bodyDescription": "Sin cuerpo de respuesta.",
          "body": null
        },
        "errorResponses": [
          {
            "status": 400,
            "reason": "El parámetro id no es un UUID válido."
          },
          {
            "status": 404,
            "reason": "La tarea no existe."
          }
        ]
      }
    ],
    "conventions": {
      "identifiers": "UUID v4 generado por el servidor y representado como cadena.",
      "timestamps": "ISO 8601 / RFC 3339 en UTC, por ejemplo 2026-01-15T09:30:00Z.",
      "updateStrategy": "PATCH para actualización parcial. No se define PUT para mantener la superficie mínima.",
      "errorFormat": {
        "contentType": "application/json",
        "structure": {
          "error": {
            "code": "string",
            "message": "string",
            "status": "integer",
            "details": "array opcional"
          }
        },
        "exampleReference": "examples.notFoundError"
      },
      "statusCodes": {
        "200": "OK: lectura o actualización correcta.",
        "201": "Created: tarea creada correctamente.",
        "204": "No Content: tarea eliminada correctamente.",
        "400": "Bad Request: JSON inválido o identificador con formato inválido.",
        "404": "Not Found: la tarea no existe.",
        "405": "Method Not Allowed: método HTTP no soportado para la ruta.",
        "415": "Unsupported Media Type: Content-Type distinto de application/json.",
        "422": "Unprocessable Entity: validación semántica fallida."
      }
    },
    "examples": {
      "task": {
        "id": "3fa85f64-5717-4562-b3fc-2c963f66afa6",
        "title": "Comprar pan",
        "completed": false,
        "createdAt": "2026-01-15T09:30:00Z",
        "updatedAt": "2026-01-15T09:30:00Z"
      },
      "taskUpdated": {
        "id": "3fa85f64-5717-4562-b3fc-2c963f66afa6",
        "title": "Comprar pan",
        "completed": true,
        "createdAt": "2026-01-15T09:30:00Z",
        "updatedAt": "2026-01-15T10:05:00Z"
      },
      "taskList": [
        {
          "id": "3fa85f64-5717-4562-b3fc-2c963f66afa6",
          "title": "Comprar pan",
          "completed": false,
          "createdAt": "2026-01-15T09:30:00Z",
          "updatedAt": "2026-01-15T09:30:00Z"
        },
        {
          "id": "7c9e6679-7425-40de-944b-e07fc1f90ae7",
          "title": "Estudiar REST",
          "completed": true,
          "createdAt": "2026-01-15T11:00:00Z",
          "updatedAt": "2026-01-15T11:20:00Z"
        }
      ],
      "validationError": {
        "error": {
          "code": "validation_error",
          "message": "El campo title es obligatorio.",
          "status": 422,
          "details": [
            {
              "field": "title",
              "issue": "required"
            }
          ]
        }
      },
      "notFoundError": {
        "error": {
          "code": "task_not_found",
          "message": "La tarea no existe.",
          "status": 404
        }
      },
      "badRequestError": {
        "error": {
          "code": "bad_request",
          "message": "El cuerpo JSON es inválido.",
          "status": 400
        }
      }
    }
  }
}
